INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 6, 'theory', 'Quiz: Functions, Scope and Closures');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 6, 0, 'What does this code print: for (var i = 0; i < 3; i++) fns.push(() => i); then a call of all the functions in fns?', '["0, 1, 2", "undefined three times", "A ReferenceError", "3, 3, 3"]', 3, 'var declares one variable for the whole function, and all the arrows see it after the loop, when i equals 3. With let you would get 0, 1, 2.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 6, 1, 'How does an arrow function differ from a regular one?', '["An arrow has no this of its own: it takes it from the environment where it was created", "An arrow cannot be called with arguments", "An arrow always runs asynchronously", "An arrow is hoisted to the top of the scope, like a declaration"]', 0, 'An arrow has no this or arguments of its own. That makes it handy for callbacks inside methods, but unsuitable as an object method.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 6, 2, 'What is a closure?', '["A function that calls itself", "A block of code in curly braces", "A function together with the environment where it was created; it remembers that environment''s variables", "A function without parameters"]', 2, 'An inner function keeps a reference to the environment where it was created, so the variables live as long as the function itself does.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 6, 3, 'What happens when you access let x before the line let x = 5;?', '["undefined is returned", "ReferenceError: the variable is in the \"temporal dead zone\"", "5 is returned", "A SyntaxError when the file loads"]', 1, 'The engine knows the name from the start of the block, but you cannot touch it before initialization. For var, undefined would be returned.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 6, 4, 'What is f(1, null) given function f(a, b = 5) { return [a, b]; }?', '["[1, null]", "[1, 5]", "[1, undefined]", "TypeError"]', 0, 'The default value is used only for undefined; null stays as it is.');
